import{_ as e}from"./chunks/hrm-feature.C2RufSLs.js";import{_ as t,o as r,c as o,a2 as d}from"./chunks/framework.CqGPl1zp.js";const i="/newx-doc/img/HRM%E4%BA%BA%E5%8A%9B%E8%B5%84%E6%BA%90/%E7%BB%84%E7%BB%87/HR%E5%B7%A5%E4%BD%9C%E5%8F%B0.png",h="/newx-doc/img/HRM%E4%BA%BA%E5%8A%9B%E8%B5%84%E6%BA%90/%E7%BB%84%E7%BB%87/%E4%B8%AA%E4%BA%BA%E5%B7%A5%E4%BD%9C%E5%8F%B0.png",l="/newx-doc/img/HRM%E4%BA%BA%E5%8A%9B%E8%B5%84%E6%BA%90/%E7%A7%BB%E5%8A%A8%E7%AB%AF/%E5%B7%A5%E4%BD%9C%E5%8F%B0.png",n="/newx-doc/img/ad/zsxq_hrm.png",c="/newx-doc/img/HRM%E4%BA%BA%E5%8A%9B%E8%B5%84%E6%BA%90/%E6%A6%82%E8%A7%88/%E6%A8%A1%E5%9D%97%E5%85%B3%E7%B3%BB.svg",E=JSON.parse('{"title":"HRM 演示","description":"","frontmatter":{},"headers":[],"relativePath":"hrm-preview.md","filePath":"hrm-preview.md","lastUpdated":null}'),u={name:"hrm-preview.md"};function m(s,a,p,_,b,f){return r(),o("div",null,[...a[0]||(a[0]=[d('<h1 id="hrm-演示" tabindex="-1">HRM 演示 <a class="header-anchor" href="#hrm-演示" aria-label="Permalink to &quot;HRM 演示&quot;">​</a></h1><h2 id="_1-演示地址" tabindex="-1">1. 演示地址 <a class="header-anchor" href="#_1-演示地址" aria-label="Permalink to &quot;1. 演示地址&quot;">​</a></h2><p>HRM（Human Resource Management，人力资源管理系统）用于维护企业从招聘、入职到考勤、社保、薪资、绩效的完整人事链路，以员工主档为中心，串联组织、招聘、考勤、社保、薪资、绩效六大业务域。</p><h3 id="_1-1-hrm-管理后台" tabindex="-1">1.1 HRM 管理后台 <a class="header-anchor" href="#_1-1-hrm-管理后台" aria-label="Permalink to &quot;1.1 HRM 管理后台&quot;">​</a></h3><ul><li>演示地址：<a href="http://dashboard-vue3.yudao.iocoder.cn/" target="_blank" rel="noreferrer">http://dashboard-vue3.yudao.iocoder.cn/</a></li><li>菜单：&quot;HRM 人力资源&quot;下的「HR 工作台」「组织管理」「招聘管理」「员工管理」「考勤管理」「社保管理」「薪资管理」「绩效管理」</li><li>仓库：<a href="https://github.com/yudaocode/yudao-ui-admin-vue3" target="_blank" rel="noreferrer">https://github.com/yudaocode/yudao-ui-admin-vue3</a> 的 <code>hrm</code> 目录，基于 Vue3 + Element Plus 实现</li></ul><p><img src="'+i+'" alt="管理后台"></p><h3 id="_1-2-hrm-员工端" tabindex="-1">1.2 HRM 员工端 <a class="header-anchor" href="#_1-2-hrm-员工端" aria-label="Permalink to &quot;1.2 HRM 员工端&quot;">​</a></h3><p>员工端不是另一套账号、前端或数据库，而是同一个管理后台下的「HRM 员工端」菜单。员工档案的 <code>user_id</code> 绑定后台账号后，该账号即可查看本人的档案、考勤、社保、工资条和绩效任务。</p><ul><li>菜单：&quot;HRM 人力资源&quot;下的「HRM 员工端」</li><li>仓库：<a href="https://github.com/yudaocode/yudao-ui-admin-vue3" target="_blank" rel="noreferrer">https://github.com/yudaocode/yudao-ui-admin-vue3</a> 的 <code>hrm/portal</code> 目录</li></ul><p>Portal 接口通过当前登录账号反查员工主档，只返回本人数据；未绑定员工档案时，页面展示开通引导。</p><p><img src="'+h+'" alt="员工端"></p><h3 id="_1-3-hrm-后端" tabindex="-1">1.3 HRM 后端 <a class="header-anchor" href="#_1-3-hrm-后端" aria-label="Permalink to &quot;1.3 HRM 后端&quot;">​</a></h3><p>支持 Spring Boot 单体、Spring Cloud 微服务架构</p><ul><li>单体仓库：<a href="https://github.com/YunaiV/ruoyi-vue-pro" target="_blank" rel="noreferrer">https://github.com/YunaiV/ruoyi-vue-pro</a> 的 <code>yudao-module-hrm</code> 模块</li><li>微服务仓库：<a href="https://github.com/YunaiV/yudao-cloud" target="_blank" rel="noreferrer">https://github.com/YunaiV/yudao-cloud</a> 的 <code>yudao-module-hrm</code> 服务</li></ul><h3 id="_1-4-hrm-移动端" tabindex="-1">1.4 HRM 移动端 <a class="header-anchor" href="#_1-4-hrm-移动端" aria-label="Permalink to &quot;1.4 HRM 移动端&quot;">​</a></h3><p>HRM 提供 uni-app 移动端，管理端与员工端都可以在手机上处理，详见 <a href="./hrm/mobile">《移动端 HRM》</a>。</p><ul><li>仓库：<a href="https://github.com/yudaocode/yudao-ui-admin-uniapp" target="_blank" rel="noreferrer">https://github.com/yudaocode/yudao-ui-admin-uniapp</a> 的 <code>pages-hrm</code> 目录</li></ul><p><img src="'+l+'" alt="移动端"></p><h2 id="_2-hrm-启动" tabindex="-1">2. HRM 启动 <a class="header-anchor" href="#_2-hrm-启动" aria-label="Permalink to &quot;2. HRM 启动&quot;">​</a></h2><p>参见 <a href="./hrm/build">《HRM 手册 —— 功能开启》</a> 文档，一般 3 分钟就可以启动完成。</p><h2 id="_3-hrm-交流" tabindex="-1">3. HRM 交流 <a class="header-anchor" href="#_3-hrm-交流" aria-label="Permalink to &quot;3. HRM 交流&quot;">​</a></h2><p>专属交流社区，欢迎扫码加入。</p><p><img src="'+n+'" alt="交流群"></p><h2 id="_4-功能描述" tabindex="-1">4. 功能描述 <a class="header-anchor" href="#_4-功能描述" aria-label="Permalink to &quot;4. 功能描述&quot;">​</a></h2><p>主要分为 6 个业务域：组织与员工、招聘管理、考勤管理、社保管理、薪资管理、绩效管理，另外提供一套面向员工的自助端。</p><p>业务以员工主档为中心：候选人办理入职后生成员工，员工再进入考勤、社保、薪资和绩效流程；员工端复用同一份员工档案，只开放本人数据和本人可办理的操作。</p><p><img src="'+e+'" alt="HRM 功能列表"></p><h2 id="_5-表结构" tabindex="-1">5. 表结构 <a class="header-anchor" href="#_5-表结构" aria-label="Permalink to &quot;5. 表结构&quot;">​</a></h2><p>HRM 共 <strong>50</strong> 张表，表名统一以 <code>hrm_</code> 为前缀。部门复用 <code>system_dept</code>、后台账号复用 <code>system_users</code>，它们不计入这 50 张表。</p><p><img src="'+c+'" alt="HRM 全表关系"></p><table tabindex="0"><thead><tr><th>模块</th><th>子前缀</th><th>表数量</th><th>核心职责</th></tr></thead><tbody><tr><td>共享配置</td><td><code>hrm_config</code></td><td>1</td><td>员工字段设置、招聘淘汰原因等业务配置</td></tr><tr><td>员工管理</td><td><code>hrm_employee*</code></td><td>12</td><td>员工主档、经历、合同、异动、离职、附件和备忘</td></tr><tr><td>招聘管理</td><td><code>hrm_recruit_*</code></td><td>5</td><td>职位、职位类型、候选人、面试和招聘渠道</td></tr><tr><td>考勤管理</td><td><code>hrm_attendance_*</code></td><td>4</td><td>考勤组、节假日、打卡和请假</td></tr><tr><td>社保管理</td><td><code>hrm_insurance_*</code></td><td>5</td><td>方案、方案项目、员工资料、月度主表和员工明细</td></tr><tr><td>薪资管理</td><td><code>hrm_salary_*</code></td><td>13</td><td>计薪配置、薪资组、工资项、定调薪、月工资和工资条</td></tr><tr><td>绩效管理</td><td><code>hrm_performance_*</code></td><td>10</td><td>模板、计划、考核实例、阶段、维度、指标、评分和申诉</td></tr></tbody></table><h3 id="_5-1-组织管理" tabindex="-1">5.1 组织管理 <a class="header-anchor" href="#_5-1-组织管理" aria-label="Permalink to &quot;5.1 组织管理&quot;">​</a></h3><p>HR、团队和个人工作台提供统计、日历与个人备忘，其中只有个人备忘落到 <code>hrm_employee_personal_note</code> 表；组织架构直接复用 System 部门，不新建 HRM 表。</p><ul><li><a href="./hrm/organization">《【组织】工作台、组织架构》</a></li></ul><h3 id="_5-2-员工管理" tabindex="-1">5.2 员工管理 <a class="header-anchor" href="#_5-2-员工管理" aria-label="Permalink to &quot;5.2 员工管理&quot;">​</a></h3><p>员工主档是 HRM 的核心，覆盖档案建立、资料维护、入职、转正、异动、离职及再次入职，并按教育、工作、合同、附件等维度扩展子档案。员工字段设置与招聘淘汰原因共用 <code>hrm_config</code> 配置表。</p><ul><li><a href="./hrm/employee">《【员工】员工管理》</a></li></ul><h3 id="_5-3-招聘管理" tabindex="-1">5.3 招聘管理 <a class="header-anchor" href="#_5-3-招聘管理" aria-label="Permalink to &quot;5.3 招聘管理&quot;">​</a></h3><p>围绕「<strong>招聘职位 → 候选人 → 面试 → Offer → 转员工</strong>」形成招聘闭环，并通过招聘渠道与淘汰原因统一基础配置。</p><ul><li><a href="./hrm/recruit">《【招聘】招聘管理》</a></li></ul><h3 id="_5-4-考勤管理" tabindex="-1">5.4 考勤管理 <a class="header-anchor" href="#_5-4-考勤管理" aria-label="Permalink to &quot;5.4 考勤管理&quot;">​</a></h3><p>考勤组定义班次、地点、WiFi、特殊日期和扣款规则；打卡记录形成日、月统计，请假由员工端发起并复用 BPM 审批。日月统计为<strong>实时计算</strong>，不落归档快照。</p><ul><li><a href="./hrm/attendance">《【考勤】考勤管理》</a></li></ul><h3 id="_5-5-社保管理" tabindex="-1">5.5 社保管理 <a class="header-anchor" href="#_5-5-社保管理" aria-label="Permalink to &quot;5.5 社保管理&quot;">​</a></h3><p>采用「<strong>当前配置 + 月度快照</strong>」设计：参保方案定义企业与个人缴费项目，员工参保档案提供核算基础，月度社保表按月归档并保留历史。</p><ul><li><a href="./hrm/insurance">《【社保】社保管理》</a></li></ul><h3 id="_5-6-薪资管理" tabindex="-1">5.6 薪资管理 <a class="header-anchor" href="#_5-6-薪资管理" aria-label="Permalink to &quot;5.6 薪资管理&quot;">​</a></h3><p>按「<strong>计薪设置 → 薪资档案 → 月度工资 → 工资条</strong>」四段组织：计薪周期、计税规则、薪资组和工资项组成基础配置；员工定调薪后进入月度工资核算，核算结果通过工资条发放给员工。</p><ul><li><a href="./hrm/salary/config">《【薪资】计薪设置、薪资档案》</a></li><li><a href="./hrm/salary/payroll">《【薪资】月度工资、工资条》</a></li></ul><h3 id="_5-7-绩效管理" tabindex="-1">5.7 绩效管理 <a class="header-anchor" href="#_5-7-绩效管理" aria-label="Permalink to &quot;5.7 绩效管理&quot;">​</a></h3><p>指标模板和结果模板用于配置绩效计划；计划启动后，参评员工依次完成制定指标、确认目标、评分、结果审核、结果确认和申诉，最终沉淀为绩效档案。</p><ul><li><a href="./hrm/performance/template-plan">《【绩效】绩效模板、绩效计划》</a></li><li><a href="./hrm/performance/assessment">《【绩效】绩效考核、绩效档案》</a></li></ul><h3 id="_5-8-员工自助" tabindex="-1">5.8 员工自助 <a class="header-anchor" href="#_5-8-员工自助" aria-label="Permalink to &quot;5.8 员工自助&quot;">​</a></h3><p>员工端提供个人工作台、本人档案、考勤与请假、社保、工资条、绩效任务和绩效档案。</p><p>管理端负责规则配置与全员管理，员工端负责查看本人数据和完成本人流程节点，因此不单独成篇，各业务手册的「员工端」小节即对应功能。</p>',55)])])}const q=t(u,[["render",m]]);export{E as __pageData,q as default};
